-- This first migration also adopts databases created before Flyway was introduced.
-- IF NOT EXISTS preserves their schema and data while recording V1 in Flyway history.
-- Future schema changes must be new versioned migrations; do not edit this file.
CREATE TABLE IF NOT EXISTS users (
    id TEXT PRIMARY KEY,
    username TEXT UNIQUE NOT NULL,
    password TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS tokens (
    id TEXT PRIMARY KEY,
    user_id TEXT NOT NULL,
    expires INTEGER NOT NULL
);

CREATE TABLE IF NOT EXISTS conversions (
    id TEXT PRIMARY KEY,
    owner TEXT NOT NULL,
    name TEXT NOT NULL,
    format TEXT NOT NULL,
    size INTEGER NOT NULL,
    pdf_size INTEGER NOT NULL,
    created TEXT NOT NULL
);

CREATE INDEX IF NOT EXISTS conversions_owner ON conversions(owner, created);
